import type {
  SchemaDescription, TableShape, ColumnShape, ReplicationRole,
} from './describe.js'

/**
 * The schema as a document a person can read.
 *
 * Committed at `docs/schema.md` and regenerated by `npm run schema:doc`.
 * `schemaDoc.test.ts` renders it again from a freshly migrated database and
 * fails when the committed copy has drifted, so the file in the repo is the
 * file the migrations produce -- not a description of it written once and
 * left behind.
 *
 * The output is deterministic: tables alphabetical, columns in their declared
 * order, indexes and foreign keys sorted. A generator whose output moves
 * around produces a diff nobody reads and a drift test nobody trusts.
 */

export function renderSchemaDoc(desc: SchemaDescription): string {
  const out: string[] = []

  out.push('# The database')
  out.push('')
  out.push('<!-- Generated by `npm run schema:doc`. Do not edit by hand:')
  out.push('     `schemaDoc.test.ts` regenerates this and fails if it has drifted. -->')
  out.push('')
  out.push(
    `Schema version **${desc.version}**, ${desc.tables.length} tables, ` +
    `read off a database built by running every migration in order.`,
  )
  out.push('')
  out.push(
    'Money is integer paise. Quantities are scaled by 10^4. Tax is basis points. ' +
    'A column named `*_amount`, `*_total`, `rate` or `value` is paise unless it says ' +
    'otherwise; `qty` columns are scaled. Nothing here is a float.',
  )
  out.push('')
  out.push(
    'The **Sync** column is read from `domain/replicaShape.ts`, which is the one ' +
    'place that decision is written down, so this table cannot disagree with what ' +
    'a merge actually carries.',
  )
  out.push('')

  out.push('## Contents')
  out.push('')
  out.push(...contents(desc))
  out.push('')

  out.push('## What travels between tills')
  out.push('')
  out.push(...replicationSummary(desc))
  out.push('')

  out.push('## Tables')
  out.push('')
  for (const table of desc.tables) {
    out.push(...renderTable(table))
    out.push('')
  }

  if (desc.views.length > 0) {
    out.push('## Views')
    out.push('')
    for (const view of desc.views) {
      out.push(`### \`${view.name}\``)
      out.push('')
      out.push('```sql')
      out.push(view.sql)
      out.push('```')
      out.push('')
    }
  }

  return `${out.join('\n').trimEnd()}\n`
}

function contents(desc: SchemaDescription): string[] {
  const names = desc.tables.map((t) => `[\`${t.name}\`](#${anchor(t.name)})`)
  const lines: string[] = []
  // Six to a line: a 45-entry bullet list is a page of scrolling before the content.
  for (let i = 0; i < names.length; i += 6) {
    lines.push(names.slice(i, i + 6).join(' · '))
    lines.push('')
  }
  return lines.slice(0, -1)
}

function replicationSummary(desc: SchemaDescription): string[] {
  const records = desc.tables.filter((t) => t.replication.kind === 'record')
  const lines = desc.tables.filter((t) => t.replication.kind === 'lines')
  const local = desc.tables.filter((t) => t.replication.kind === 'local')
  const undecided = desc.tables.filter((t) => t.replication.kind === 'undecided')

  const out: string[] = []
  out.push(`- **${records.length} records** travel as themselves and are what the merge rule compares.`)
  out.push(`- **${lines.length} line tables** travel only inside their parent document. Half a bill is not a smaller bill.`)
  out.push(`- **${local.length} tables stay put.** Each one has a reason, printed with it below.`)
  if (undecided.length > 0) {
    out.push(
      `- **${undecided.length} undecided** — in the database and in neither list. ` +
      `\`replicaShape.test.ts\` fails on these: ${undecided.map((t) => `\`${t.name}\``).join(', ')}.`,
    )
  }
  return out
}

function renderTable(table: TableShape): string[] {
  const out: string[] = []

  out.push(`### \`${table.name}\``)
  out.push('')
  out.push(...replicationLine(table.replication))
  out.push('')

  out.push('| Column | Type | Null | Default | Key |')
  out.push('|---|---|---|---|---|')
  for (const column of table.columns) out.push(columnRow(table, column))
  out.push('')

  if (table.foreignKeys.length > 0) {
    out.push('Points at:')
    out.push('')
    for (const fk of table.foreignKeys) {
      const target = fk.to === null ? `\`${fk.table}\` (its primary key)` : `\`${fk.table}.${fk.to}\``
      const rules = [
        fk.onDelete === 'NO ACTION' ? null : `on delete ${fk.onDelete.toLowerCase()}`,
        fk.onUpdate === 'NO ACTION' ? null : `on update ${fk.onUpdate.toLowerCase()}`,
      ].filter((r): r is string => r !== null)
      out.push(`- \`${fk.from}\` → ${target}${rules.length > 0 ? ` (${rules.join(', ')})` : ''}`)
    }
    out.push('')
  }

  if (table.indexes.length > 0) {
    out.push('Indexes:')
    out.push('')
    for (const index of table.indexes) {
      const where = index.sql !== null && / WHERE /i.test(index.sql)
        ? ` — partial: ${index.sql.replace(/^.*? WHERE /is, '').trim()}`
        : ''
      const on = index.columns.map((c) => `\`${c}\``).join(', ')
      out.push(index.sql === null && index.name.startsWith('unique (')
        ? `- UNIQUE constraint on ${on}`
        : `- \`${index.name}\`${index.unique ? ' (unique)' : ''} on ${on}${where}`)
    }
    out.push('')
  }

  if (table.triggers.length > 0) {
    out.push(
      `Triggers: ${table.triggers.map((t) => `\`${t}\``).join(', ')}.`,
    )
    out.push('')
  }

  out.push('<details><summary>CREATE TABLE</summary>')
  out.push('')
  out.push('```sql')
  out.push(table.sql)
  out.push('```')
  out.push('')
  out.push('</details>')

  return out
}

function columnRow(table: TableShape, column: ColumnShape): string {
  const fk = table.foreignKeys.find((f) => f.from === column.name)
  const key = [
    column.pk > 0 ? 'pk' : null,
    fk !== undefined ? `→ ${fk.table}` : null,
    uniqueness(table, column.name),
  ].filter((k): k is string => k !== null).join(', ')

  const cells = [
    `\`${column.name}\``,
    column.type === '' ? '—' : `\`${column.type}\``,
    column.notNull ? 'no' : 'yes',
    column.default === null ? '—' : `\`${column.default}\``,
    key,
  ]
  return `| ${cells.map(cell).join(' | ')} |`
}

/** A pipe inside a table cell ends the cell, and at least one default has one. */
function cell(text: string): string {
  return text.replace(/\|/g, '\\|')
}

function replicationLine(role: ReplicationRole): string[] {
  switch (role.kind) {
    case 'record':
      return [
        `**Syncs** as a record, keyed by \`${role.key}\`` +
        (role.travels === null ? '.' : `, but only the rows where \`${role.travels}\`.`),
      ]
    case 'lines':
      return [
        `**Syncs** inside \`${role.parent}\`, joined by \`${role.parentKey}\`. ` +
        'Never on its own: applying the parent replaces these rows outright.',
      ]
    case 'local':
      return [`**Stays on this till** — ${role.why}.`]
    case 'undecided':
      return ['**Undecided** — not in `replicaShape.ts`. This is a failing test, not a design.']
  }
}

/** GitHub keeps underscores in a heading's anchor and drops the backticks. */
function anchor(name: string): string {
  return name.toLowerCase()
}

/**
 * What the Key cell says about a column being unique: plainly unique, unique
 * only among rows a condition picks out -- `cash_sessions.register_id` is
 * unique among open sessions, not across them -- or nothing.
 */
function uniqueness(table: TableShape, column: string): string | null {
  const own = table.indexes.filter((i) => i.unique && i.columns.length === 1 && i.columns[0] === column)
  if (own.length === 0) return null
  const whole = own.find((i) => i.sql === null || !/ WHERE /i.test(i.sql))
  if (whole) return 'unique'
  const partial = own[0]!.sql!.replace(/^.*? WHERE /is, '').trim()
  return `unique where ${partial}`
}
